INSERT INTO `partidas` (`id`, `capitulo_id`, `subcapitulo`, `partida_generica`, `codigo`, `nombre`, `descripcion`, `activo`, `created_at`, `updated_at`, `deleted_at`) VALUES
(3, 1, '1100', '', '11101', 'Dietas.- Asignaciones para remuneraciones a los Diputados, Senadores, Asambleístas, Regidores y Síndicos.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(4, 1, '1100', '', '11102', 'Emolumentos.- Asignaciones para remuneraciones a los delegados y subdelegados que nombra el H. Ayuntamiento.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(5, 1, '1100', '', '11301', 'Sueldos base al personal permanente.- Asignaciones para remuneraciones al personal civil, de base o de confianza, de carácter permanente que preste sus servicios en los entes públicos. Los montos que importen estas remuneraciones serán fijados de acuerdo con los catálogos institucionales de puestos de los entes públicos.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(6, 1, '1100', '', '11302', 'Salarios al personal de Confianza.- Asignaciones destinadas a cubrir las remuneraciones a personal de confianza, de las dependencias.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(7, 1, '1200', '', '12101', 'Honorarios asimilables a salarios.- Asignaciones destinadas a cubrir el pago por la prestación de servicios contratados con personas físicas, como profesionistas, técnicos, expertos y peritos, entre otros, por estudios, obras o trabajos determinados que correspondan a su especialidad. El pago de honorarios deberá sujetarse a las disposiciones aplicables. Esta partida excluye los servicios profesionales contratados con personas físicas o morales previstos en el Capítulo 3000 Servicios Generales.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(8, 1, '1200', '', '12102', 'Honorarios.- Asignaciones destinadas a cubrir el pago por la prestación de servicios personales contratados, bajo este régimen fiscal, para el desempeño de actividades propias de la administración municipal.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(9, 1, '1200', '', '12201', 'Sueldos base al personal eventual.- Asignaciones destinadas a cubrir las remuneraciones para el pago al personal de carácter transitorio que preste sus servicios en los entes públicos.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(10, 1, '1200', '', '12301', 'Retribuciones por servicios de carácter social.- Asignaciones destinadas a cubrir las remuneraciones a profesionistas de las diversas carreras o especialidades técnicas que presten su servicio social en los entes públicos.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(11, 1, '1300', '', '13101', 'Primas por años de servicios efectivos prestados.- Asignaciones adicionales como complemento al sueldo del personal al servicio de los entes públicos, por años de servicios efectivos prestados, de acuerdo con la legislación aplicable.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(12, 1, '1300', '', '13201', 'Primas de vacaciones.- Asignaciones al personal que tenga derecho a vacaciones o preste sus servicios en domingo.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(13, 1, '1300', '', '13202', 'Prima Dominical.- Asignaciones al personal que  preste sus servicios en domingo.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(14, 1, '1300', '', '13203', 'Gratificación fin de año.- Asignaciones al personal que tenga derecho a aguinaldo o gratificación de fin de año al personal civil y militar al servicio de los entes públicos.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(15, 1, '1300', '', '13301', 'Remuneraciones por horas extraordinarias al personal administrativo.- Asignaciones por remuneraciones a que tenga derecho el personal de los entes públicos por servicios prestados en horas que se realizan excediendo la duración máxima de la jornada de trabajo, guardias o turnos opcionales.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(16, 1, '1300', '', '13302', 'Remuneraciones por horas extraordinarias al personal operativo.- Asignaciones por remuneraciones a que tenga derecho el personal de los entes públicos por servicios prestados en horas que se realizan excediendo la duración máxima de la jornada de trabajo, guardias o turnos opcionales.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(17, 1, '1300', '', '13401', 'Compensaciones.- Asignaciones destinadas a cubrir las percepciones que se otorgan a los servidores públicos bajo el esquema de compensaciones que determinen las disposiciones aplicables.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(18, 1, '1300', '', '13402', 'Retribuciones por actividades especiales.- Asignaciones destinadas a cubrir al personal de las dependencias, el pago por servicios prestados fuera de la jornada normal de trabajo relacionados con su cargo o servicios especiales que desempeñen.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(19, 1, '1300', '', '13403', 'Compensaciones extraordinarias.- Asignaciones destinadas a cubrir al personal de las dependencias, el pago por programas especiales.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(20, 1, '1300', '', '13501', 'Sobrehaberes.- Remuneraciones adicionales que se cubre al personal militar en activo en atención al incremento en el costo de la vida o insalubridad del lugar donde preste sus servicios.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(21, 1, '1400', '', '14101', 'Aportaciones de seguridad social.- Asignaciones destinadas a cubrir la aportación de los entes públicos, por concepto de seguridad social, en los términos de la legislación vigente.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(22, 1, '1400', '', '14201', 'Aportaciones a fondos de vivienda.- Asignaciones destinadas a cubrir las aportaciones que corresponden a los entes públicos para proporcionar vivienda a su personal, de acuerdo con las disposiciones legales vigentes.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(23, 1, '1400', '', '14301', 'Aportaciones al sistema para el retiro.- Asignaciones destinadas a cubrir los montos de las aportaciones de los entes públicos a favor del Sistema para el Retiro, correspondientes a los trabajadores al servicio de los mismos.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(24, 1, '1400', '', '14401', 'Aportaciones para seguros.- Asignaciones destinadas a cubrir las primas que corresponden a los entes públicos por concepto de seguro de vida, seguro de gastos médicos del personal a su servicio; así como, los seguros de responsabilidad civil y asistencia legal, en los términos de la legislación vigente. Incluye las primas que corresponden al Gobierno Federal por concepto de seguro de vida del personal militar.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(25, 1, '1500', '', '15101', 'Cuotas para el fondo de ahorro.- Asignaciones destinadas a cubrir las cuotas que corresponden a los entes públicos para la constitución del fondo de ahorro del personal civil, según acuerdos contractuales establecidos. Incluye cuotas para la constitución del fondo de ahorro.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(26, 1, '1500', '', '15102', 'Cuotas para el fondo de ahorro para el retiro.- Asignaciones que se destinan para el pago del fondo de ahorro para el retiro para los funcionarios de elección popular, de acuerdo a lo dispuesto por la Ley para el Ejercicio y Control de los Recursos Públicos para el Estado y los Municipios de Guanajuato.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(27, 1, '1500', '', '15201', 'Indemnizaciones.- Asignaciones destinadas a cubrir indemnizaciones al personal conforme a la legislación aplicable; tales como: por accidente de trabajo, por despido, entre otros.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(28, 1, '1500', '', '15202', 'Liquidaciones por indemnizaciones y por sueldos y salarios caídos.- Asignaciones destinadas a cubrir el pago de indemnización por liquidación y el pago de salarios y sueldos caídos cuando se separa a un trabajador.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(29, 1, '1500', '', '15301', 'Prestaciones y haberes de retiro.- Erogaciones que los entes públicos realizan en beneficio de sus empleados por jubilaciones, haberes de retiro, pensiones, retiro voluntario entre otros, cuando estas prestaciones no sean cubiertas por las instituciones de seguridad social. Incluye las asignaciones por concepto de aguinaldo a favor de pensionistas, cuyo pago se realice con cargo al erario. Incluye compensaciones de retiro a favor del personal del Servicio Exterior Mexicano, en los términos de la ley de la materia.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(30, 1, '1500', '', '15401', 'Liquidación prima quinquenal.- Asignaciones destinadas al pago de las liquidaciones de las primas quinquenales, a los funcionarios y empleados al servicio de las dependencias.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(31, 1, '1500', '', '15402', 'Ayudas para gastos de defunción.- Asignaciones destinadas a cubrir el pago por  ayuda para gastos de defunción, a favor de los empleados de base y de confianza que laboran para las dependencias.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(32, 1, '1500', '', '15403', 'Ayuda de transporte.- Asignaciones que se destinan para cubrir el pago por concepto de ayuda de transporte a los empleados de base y de confianza, al servicio del municipio, de conformidad con los planes autorizados.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(33, 1, '1500', '', '15404', 'Ayuda para educación.- Asignaciones que las dependencias destinan para cubrir el pago por concepto de ayuda para educación del personal de base y de confianza, como parte de los planes de previsión social.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
(34, 1, '1500', '', '15405', 'Ayuda para despensa.- Asignaciones que se destinan para cubrir el pago por concepto de ayuda para despensa al personal de base y de confianza, como parte de los planes de previsión social.', 'Importado Masivamente', 1, '2026-01-12 22:08:04', '2026-01-12 22:08:04', NULL),
